edges = [(0,5),(2,7),(1,4),(3,6)]
V = 8
# check bipartite via 2-coloring
from collections import defaultdict, deque
adj = defaultdict(list)
for u,v in edges:
    adj[u].append(v); adj[v].append(u)
color = {}
for s in range(V):
    if s in color: continue
    color[s]=0
    q=deque([s])
    while q:
        x=q.popleft()
        for y in adj[x]:
            if y not in color:
                color[y]=1-color[x]; q.append(y)
            elif color[y]==color[x]:
                print("not bipartite")
deg = {v: len(adj[v]) for v in range(V)}
print("degrees:", deg)
print("all deg>=1:", all(d>=1 for d in deg.values()))
